using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;

namespace SearchIndexService
{
    public class TokenBucket
    {
        private readonly int _maxTokens;
        private readonly int _refillRate;
        private int _currentTokens;
        private DateTime _lastRefill;
        private readonly object _lock = new object();

        public TokenBucket(int maxTokens, int refillRate)
        {
            _maxTokens = maxTokens;
            _refillRate = refillRate;
            _currentTokens = maxTokens;
            _lastRefill = DateTime.UtcNow;
        }

        public bool TryConsume()
        {
            lock (_lock)
            {
                Refill();
                if (_currentTokens > 0)
                {
                    _currentTokens--;
                    return true;
                }
                return false;
            }
        }

        private void Refill()
        {
            var now = DateTime.UtcNow;
            var elapsed = (now - _lastRefill).TotalSeconds;
            var tokensToAdd = (int)(elapsed * _refillRate);
            if (tokensToAdd > 0)
            {
                _currentTokens = Math.Min(_maxTokens, _currentTokens + tokensToAdd);
                _lastRefill = now;
            }
        }
    }

    public class SearchIndex
    {
        private readonly Dictionary<string, HashSet<int>> _invertedIndex;
        private readonly TokenBucket _rateLimiter;
        private readonly int _maxRetries = 3;
        private readonly int _maxQueryTerms = 20;
        private const int MaxWildcardExpansion = 50;

        public SearchIndex()
        {
            _invertedIndex = new Dictionary<string, HashSet<int>>();
            _rateLimiter = new TokenBucket(100, 10);
        }

        public void IndexDocument(int docId, string content)
        {
            if (string.IsNullOrEmpty(content)) return;
            var tokens = Tokenize(content);
            foreach (var token in tokens)
            {
                var normalizedToken = NormalizeToken(token);
                if (!_invertedIndex.ContainsKey(normalizedToken))
                    _invertedIndex[normalizedToken] = new HashSet<int>();
                _invertedIndex[normalizedToken].Add(docId);
            }
        }

        public SearchResult Search(string query, int retryCount = 0)
        {
            if (!_rateLimiter.TryConsume())
            {
                if (retryCount < _maxRetries)
                {
                    Thread.Sleep(100 * (retryCount + 1));
                    return Search(query, retryCount + 1);
                }
                return new SearchResult { Error = "Rate limit exceeded" };
            }

            var terms = Tokenize(query);
            if (terms.Count > _maxQueryTerms)
                return new SearchResult { Error = "Too many query terms" };

            var results = ExecuteSearch(terms);
            return new SearchResult { DocumentIds = results };
        }

        private List<int> ExecuteSearch(List<string> terms)
        {
            var normalizedTerms = terms.Select(NormalizeToken).ToList();
            var matchingSets = new List<HashSet<int>>();

            foreach (var term in normalizedTerms)
            {
                if (_invertedIndex.TryGetValue(term, out var docSet))
                    matchingSets.Add(docSet);
            }

            if (matchingSets.Count == 0)
                return new List<int>();

            // Compute intersection starting from smallest set for efficiency
            matchingSets.Sort((a, b) => a.Count.CompareTo(b.Count));
            var result = matchingSets[0];
            for (int i = 1; i < matchingSets.Count; i++)
            {
                result = ComputeIntersection(result, matchingSets[i]);
            }

            return result.OrderBy(id => id).ToList();
        }

        private HashSet<int> ComputeIntersection(HashSet<int> setA, HashSet<int> setB)
        {
            var intersection = new HashSet<int>();
            // Iterate over the smaller set for O(min(|A|,|B|)) complexity
            var smaller = setA.Count <= setB.Count ? setA : setB;
            var larger = setA.Count <= setB.Count ? setB : setA;
            foreach (var item in smaller)
            {
                if (larger.Contains(item))
                    intersection.Add(item);
            }
            return intersection;
        }

        private string NormalizeToken(string token)
        {
            // Normalize using case folding and Unicode NFKD decomposition
            var normalized = token.ToLowerInvariant();
            normalized = normalized.Normalize(NormalizationForm.FormKD);
            // Strip diacritics by removing non-spacing marks
            var sb = new StringBuilder();
            foreach (var c in normalized)
            {
                if (System.Globalization.CharUnicodeInfo.GetUnicodeCategory(c) !=
                    System.Globalization.UnicodeCategory.NonSpacingMark)
                    sb.Append(c);
            }
            return sb.ToString();
        }

        private List<string> Tokenize(string input)
        {
            // Split on whitespace and punctuation, generate prefix expansions for wildcard support
            var baseTokens = input.Split(new[] { ' ', '\t', '\n', '\r', ',', '.', ';', '!' },
                StringSplitOptions.RemoveEmptyEntries);
            var expanded = new List<string>();
            foreach (var token in baseTokens)
            {
                if (token.EndsWith("*"))
                {
                    // Wildcard: expand to matching keys with bounded expansion
                    var prefix = token.TrimEnd('*');
                    if (prefix.Length >= 2)
                    {
                        var matchingKeys = _invertedIndex.Keys
                            .Where(k => k.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                            .Take(MaxWildcardExpansion)
                            .ToList();
                        expanded.AddRange(matchingKeys);
                    }
                }
                else
                {
                    expanded.Add(token);
                }
            }
            return expanded;
        }
    }

    public class SearchResult
    {
        public List<int> DocumentIds { get; set; } = new List<int>();
        public string Error { get; set; }
    }
}
